maml:description.maml:para:
Use this command to understand extraction reliability signals such as viewport, locale, storage keys,
failed requests, console errors, Fetch/XHR calls, and WebSocket activity. It reports diagnostics only;
it does not attempt to hide automation or bypass site protections.

command:example.dev:code:
Select-HtmlData -Url https://example.org/products -ItemSelector '.product-card' -Property @{
    Name = '.product-title'
    Price = '.product-price'
    Link = @{ Selector = 'a'; Attribute = 'href' }
}

$html = @'

import value from "./settings.js";
window.$Config = { sCtx: "from-module" };


window.$Config = { sCtx: "from-script" };

'@

Select-HtmlJavaScriptVariable -Content $html -Name '$Config' -PropertyPath sCtx |
    Select-Object -First 1

$html = @'
$Config = { sCtx: "first" };
$Config = { sCtx: "second" };
'@
$values = Select-HtmlJavaScriptVariable -Content $html -Name '$Config' -PropertyPath sCtx $values | Select-Object -First 1 $values | Select-Object -Last 1

$script = @'
const settings = {
    apiKey: "abc",
    enabled: true
};
'@

Select-JavaScriptAstNode -Source $script -Type Script,ObjectExpression -IncludeRoot

$module = @'
import value from "./settings.js";
export const settings = {
    enabled: true
};
'@

Select-JavaScriptAstNode -Source $module -Module -Type ImportDeclaration,ExportNamedDeclaration

$script = @'
window.$Config = {
    auth: {
        urls: {
            logout: "https://example.com/logout"
        }
    }
}
'@

Select-JavaScriptVariable -Source $script -Name '$Config' -PropertyPath auth.urls.logout

$script = @'
const cfg = {
    [key]: "dynamic",
    token: "old",
    ...override,
    items: ["first", ...extra, "last"],
    safe: "after"
};

const enabled = !window.disabled;
'@

Select-JavaScriptVariable -Source $script -Name cfg -PropertyPath key,token,items.0,items.2,safe
Select-JavaScriptVariable -Source $script -Name enabled
